functions.getGridWidth:
function getGridWidth() {
		try {
			var w = window.parent.$("#screensWrapper").width();
			if(w>100)
				return window.parent.$("#screensWrapper").width()-10;
			else
				return $(window).width()-10;
		} catch (e) {
			console.log(e.message);
			return $(window).width()-10;
		}
	}

functions.shortcutKey:
function shortcutKey(){ 		
    	$(document).bind('keydown', function(e) {
    		var keyCode = (e.keyCode) ? e.keyCode : ((e.charCode) ? e.charCode : e.which);
    		if (e.originalEvent.altKey) {
    			// ALT + S     Search                   
    			if (keyCode === 83) {
    				reloadSearchGrid();
    				e.preventDefault();
    				return false;

    			}
    			// ALT + N      Reset                 
    			if (keyCode == 78) {
    				resetAll();
    				e.preventDefault();
    				return false;
    			}
    			// ALT + F    Add New
    			if (keyCode == 70){
    				addnew();
    				e.preventDefault();
    				return false;
    			}

    		}
    	});
    }

functions.changeStatus:
function changeStatus(seqId, clientId, status){

			if(seqId == undefined || status == undefined || (clientId == undefined && false)){
				window.parent.showAlert('Something Went Wrong');
				return false;
			} 
			else if(status == 0){

				if (confirm("Do You Want To Activate this API?")) {
					var statusResponse = $.ajax({
						url : "generateApiKey?seqId="+seqId+"&clientId="+clientId,

						type : "POST",
						dataType : "json",
						async : false
					}).responseText;

					statusResponse = jQuery.parseJSON(statusResponse);

					if (statusResponse.status) {
						reloadSearchGrid();
						window.parent.showAlert(statusResponse.jsonMessage);

					} else {
						$("#apikey").html("");
						window.parent.showAlert(statusResponse.jsonMessage);
					}
				}
			}
			else if(status == 1){
				if (confirm("admin.deapiactivate")) {
					var statusResponse = $.ajax({
						url : "deactivateApiKey?seqId="+seqId+"&clientId="+clientId,

						type : "POST",
						dataType : "json",
						async : false
					}).responseText;

					statusResponse = jQuery.parseJSON(statusResponse);

					if (statusResponse.status) {
						reloadSearchGrid();
						window.parent.showAlert(statusResponse.jsonMessage);
					} else {
						$("#apikey").html("");
						window.parent.showAlert(statusResponse.jsonMessage);
					}
				}
			}		
		}

functions.reloadSearchGrid:
function reloadSearchGrid(event) {
			var clientId 	= $("#gs_clientStr").val();
			var status 		= $("#gs_status").val();

			$("#apiKeysTable").jqGrid('setGridParam', {
				datatype : 'json',
				page : 1,
				postData : {
					clientId		:clientId,
					status			:status,
					REQ_SEARCH_FLAG : true
				},
				url : "jsonGetApiKeys",
				search : true				
			}).trigger('reloadGrid');					
		}

